	runner := &ciscoRecordingCommandRunner{output: `{"ok":true}`}
	opts, err := ParseArgs([]string{target, "--scanner", "cisco"})
	if err != nil {
		t.Fatal(err)
	}
	artifact, err := Run(opts, RunContext{
		Env:           map[string]string{},
		CommandRunner: runner,
	})
	if err != nil {
		t.Fatal(err)
	}
	result := artifact.Scanners["cisco"]
	if result.Status == "skipped" {
		t.Fatalf("generic skipped result leaked through: %#v", result)
	}
	if strings.Contains(result.Error, "foundation slice") {
		t.Fatalf("generic foundation skip leaked through: %q", result.Error)
	}
}

type ciscoRecordingCommandRunner struct {
	calls    []commandCall
	output   string
	stderr   string
	err      error
	exitCode *int
}

func (r *ciscoRecordingCommandRunner) Run(command string, args []string, cwd string, timeout time.Duration) (CommandOutput, error) {
	r.calls = append(r.calls, commandCall{command: command, args: append([]string(nil), args...), cwd: cwd})
	if r.output != "" {
		outputPath := argValue(args, "--output")
		if outputPath != "" {
			if err := os.WriteFile(outputPath, []byte(r.output), 0o644); err != nil {
				return CommandOutput{Stderr: r.stderr}, err
			}
		}
	}
	return CommandOutput{Stderr: r.stderr, ExitCode: r.exitCode}, r.err
}

func argValue(args []string, name string) string {
	for i, arg := range args {
		if arg == name && i+1 < len(args) {
			return args[i+1]
		}
	}
	return ""
}

package runner

import (
	"context"
	"errors"
	"math"
	"net/http"
	"net/http/httptest"
	"strconv"
	"sync/atomic"
	"testing"
	"time"
)

func TestHuggingFaceRowsBackoffAvoidsDurationOverflow(t *testing.T) {
	for _, tc := range []struct {
		header string
		want   time.Duration
	}{
		{"0", 0},
		{"3600", time.Hour},
		{"9223372036", 9223372036 * time.Second},
		{"9223372037", time.Duration(math.MaxInt64)},
		{strconv.FormatUint(math.MaxUint64, 10), time.Duration(math.MaxInt64)},
		{"18446744073709551616", time.Duration(math.MaxInt64)},
		{"-1", huggingFaceRowsRetryDelay},
		{"invalid", huggingFaceRowsRetryDelay},
		{"18446744073709551616invalid", huggingFaceRowsRetryDelay},
	} {
		t.Run(tc.header, func(t *testing.T) {
			if got := huggingFaceRowsBackoff(1, http.Header{"Retry-After": {tc.header}}); got != tc.want {
				t.Fatalf("backoff = %s, want %s", got, tc.want)
			}
		})
	}
}

func TestHuggingFaceRowsLongCooldownWaitsForDeadline(t *testing.T) {
	for _, header := range []string{"3600", "9223372037", time.Now().Add(time.Hour).UTC().Format(http.TimeFormat)} {
		t.Run(header, func(t *testing.T) {
			var requests atomic.Int32
			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
				requests.Add(1)
				w.Header().Set("Retry-After", header)
				w.WriteHeader(http.StatusTooManyRequests)
			}))
			defer server.Close()
			ctx, cancel := context.WithTimeout(context.Background(), 250*time.Millisecond)
			defer cancel()
			client := HuggingFaceBenchmarkClient{Endpoint: server.URL, Context: ctx}
			_, err := client.FetchOpenClawRows("OpenClaw/clawhub-security-signals", "eval_holdout", 0, 1)
			if !errors.Is(err, context.DeadlineExceeded) {
				t.Fatalf("fetch error = %v, want deadline exceeded", err)
			}
			if got := requests.Load(); got != 1 {
				t.Fatalf("requests = %d, want one request before deadline", got)
			}
		})
	}
}

import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import test from 'node:test';

const scriptPath = fileURLToPath(new URL('./publish-security-signals-results.sh', import.meta.url));

function fixture(t) {
  const root = mkdtempSync(join(tmpdir(), 'clawscan-publish-'));
  t.after(() => rmSync(root, { recursive: true, force: true }));
  const bin = join(root, 'bin');
  mkdirSync(bin);
  writeFileSync(join(bin, 'hf'), '#!/bin/sh\nprintf "%s\\n" "$@" > "$HF_ARGS_FILE"\n', { mode: 0o755 });
  const argsFile = join(root, 'hf-args');
  const output = join(root, 'results.jsonl');
  return {
    argsFile,
    output,
    run(mode, token = '') {
      return spawnSync('bash', [scriptPath, mode, '--root', join(root, 'submissions'), '--output', output], {
        encoding: 'utf8',
        env: { PATH: `${bin}:/usr/bin:/bin`, HF_TOKEN: token, HF_ARGS_FILE: argsFile },
      });
    },
  };
}

test('publishes through hf without passing credentials in arguments', (t) => {
  const f = fixture(t);
  const result = f.run('--publish', 'fixture');
  assert.equal(result.status, 0, result.stderr);
  assert.deepEqual(readFileSync(f.argsFile, 'utf8').trim().split('\n'), [
    'upload', 'OpenClaw/clawhub-security-signals-results', f.output, 'results.jsonl', '--repo-type', 'dataset',
  ]);
  assert.equal(readFileSync(f.output, 'utf8'), '');
});

test('dry run writes a payload without invoking hf', (t) => {
  const f = fixture(t);
  const result = f.run('--dry-run');
  assert.equal(result.status, 0, result.stderr);
  assert.equal(readFileSync(f.output, 'utf8'), '');
  assert.equal(existsSync(f.argsFile), false);
});

test('publishing still requires a token', (t) => {
  const f = fixture(t);
  const result = f.run('--publish');
  assert.notEqual(result.status, 0);
  assert.match(result.stderr, /HF_TOKEN is required/);
  assert.equal(existsSync(f.argsFile), false);
});

package main

import (
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"strings"
)

type benchmarkArtifact struct {
	Benchmark benchmarkMetadata `json:"benchmark"`
	Summary   benchmarkSummary  `json:"summary"`
}

type benchmarkMetadata struct {
	ID     string `json:"id"`
	Split  string `json:"split"`
	Offset int    `json:"offset"`
	Limit  int    `json:"limit"`
	Rows   int    `json:"rows"`
}

type benchmarkSummary struct {
	CaseCount  int                        `json:"caseCount"`
	Evaluation benchmarkEvaluationSummary `json:"evaluation"`
}

type benchmarkEvaluationSummary struct {
	Scored     int     `json:"scored"`
	Correct    int     `json:"correct"`
	Incorrect  int     `json:"incorrect"`
	Abstained  int     `json:"abstained"`
	Unscorable int     `json:"unscorable"`
	Errors     int     `json:"errors"`
	Accuracy   float64 `json:"accuracy"`
}

type benchmarkBlockOptions struct {
	Profile     string
	Artifact    string
	WorkflowURL string
	Commit      string
}

func main() {
	if err := run(os.Args[1:], os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		os.Exit(1)
	}
}

func run(args []string, stdout io.Writer) error {
	flags := flag.NewFlagSet("update-benchmark-readme", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	artifactPath := flags.String("artifact", "", "benchmark artifact JSON path")
	readmePath := flags.String("readme", "README.md", "README path")
	profile := flags.String("profile", "clawhub", "profile marker id")
	workflowURL := flags.String("workflow-url", "", "workflow run URL")
	commit := flags.String("commit", "", "commit SHA or ref")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *artifactPath == "" {
		return errors.New("missing required --artifact")
	}
	if *profile == "" {
		return errors.New("missing required --profile")
	}

	artifact, err := readBenchmarkArtifact(*artifactPath)
	if err != nil {
		return err
	}
	readme, err := os.ReadFile(*readmePath)
	if err != nil {
		return fmt.Errorf("read README %s: %w", *readmePath, err)
	}
	block := renderBenchmarkBlock(artifact, benchmarkBlockOptions{
		Profile:     *profile,
		Artifact:    *artifactPath,
		WorkflowURL: *workflowURL,
		Commit:      *commit,
	})
	updated, err := updateReadmeBenchmarkBlock(string(readme), *profile, block)
	if err != nil {
		return err
	}
	if err := os.WriteFile(*readmePath, []byte(updated), 0o644); err != nil {
		return fmt.Errorf("write README %s: %w", *readmePath, err)
	}
	fmt.Fprint(stdout, block)
	return nil
}

func readBenchmarkArtifact(path string) (benchmarkArtifact, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return benchmarkArtifact{}, fmt.Errorf("read benchmark artifact %s: %w", path, err)
	}
	var artifact benchmarkArtifact
	if err := json.Unmarshal(data, &artifact); err != nil {
		return benchmarkArtifact{}, fmt.Errorf("parse benchmark artifact %s: %w", path, err)
	}
	if artifact.Benchmark.ID == "" {
		return benchmarkArtifact{}, fmt.Errorf("benchmark artifact %s missing benchmark.id", path)
	}
	return artifact, nil
}

func renderBenchmarkBlock(artifact benchmarkArtifact, opts benchmarkBlockOptions) string {
	caseCount := artifact.Summary.CaseCount
	if caseCount == 0 {
		caseCount = artifact.Benchmark.Rows
	}
	lines := []string{
		benchmarkStartMarker(opts.Profile),
		fmt.Sprintf("Profile: `%s`", opts.Profile),
		fmt.Sprintf("Benchmark: `%s` (`%s` split)", artifact.Benchmark.ID, artifact.Benchmark.Split),
		fmt.Sprintf("Cases: `%d`", caseCount),
		fmt.Sprintf("Accuracy: `%.4f`", artifact.Summary.Evaluation.Accuracy),
		fmt.Sprintf(
			"Scored: `%d`, correct: `%d`, incorrect: `%d`, abstained: `%d`, unscorable: `%d`, errors: `%d`",
			artifact.Summary.Evaluation.Scored,
			artifact.Summary.Evaluation.Correct,
			artifact.Summary.Evaluation.Incorrect,
			artifact.Summary.Evaluation.Abstained,
			artifact.Summary.Evaluation.Unscorable,
			artifact.Summary.Evaluation.Errors,
		),
	}
	if opts.Artifact != "" {
		lines = append(lines, fmt.Sprintf("Artifact: `%s`", opts.Artifact))
	}
	if opts.WorkflowURL != "" {
		lines = append(lines, "Workflow run: "+opts.WorkflowURL)
	}
	if opts.Commit != "" {
		lines = append(lines, fmt.Sprintf("Commit: `%s`", opts.Commit))
	}
	lines = append(lines, benchmarkEndMarker(opts.Profile), "")
	return strings.Join(lines, "\n")
}

func updateReadmeBenchmarkBlock(readme string, profile string, replacement string) (string, error) {
	start := benchmarkStartMarker(profile)
	end := benchmarkEndMarker(profile)
	startIndex := strings.Index(readme, start)
	endIndex := strings.Index(readme, end)
	if startIndex == -1 || endIndex == -1 || endIndex < startIndex {
		return "", fmt.Errorf("missing benchmark marker pair for profile %s", profile)
	}
	endIndex += len(end)
	if strings.HasPrefix(readme[endIndex:], "\r\n") {
		endIndex += 2
	} else if strings.HasPrefix(readme[endIndex:], "\n") {
		endIndex++
	}

	if !strings.Contains(replacement, start) || !strings.Contains(replacement, end) {
		replacement = start + "\n" + strings.Trim(replacement, "\n") + "\n" + end
	}
	if !strings.HasSuffix(replacement, "\n") {
		replacement += "\n"
	}
	return readme[:startIndex] + replacement + readme[endIndex:], nil
}

func benchmarkStartMarker(profile string) string {
	return fmt.Sprintf("<!-- clawscan-benchmark:%s:start -->", profile)
}

func benchmarkEndMarker(profile string) string {
	return fmt.Sprintf("<!-- clawscan-benchmark:%s:end -->", profile)
}

name: ClawSweeper Dispatch

on:
  issues:
    types: [opened, reopened, edited, labeled, unlabeled]
  issue_comment:
    types: [created, edited]
  pull_request_target: # zizmor: ignore[dangerous-triggers] maintainer-owned external dispatch; no checkout or untrusted PR code execution
    types: [opened, reopened, synchronize, ready_for_review, edited, labeled, unlabeled]

permissions:
  contents: read

concurrency:
  group: clawsweeper-dispatch-${{ github.repository }}-${{ github.event.issue.number || github.event.pull_request.number || github.run_id }}
  cancel-in-progress: ${{ github.event.action == 'edited' || github.event.action == 'synchronize' || github.event.action == 'ready_for_review' }}

jobs:
  dispatch:
    runs-on: ubuntu-latest
    if: ${{ !(endsWith(github.actor, '[bot]') && (github.event.action == 'labeled' || github.event.action == 'unlabeled')) }}
    env:
      HAS_CLAWSWEEPER_APP_PRIVATE_KEY: ${{ secrets.CLAWSWEEPER_APP_PRIVATE_KEY != '' }}
      CLAWSWEEPER_APP_ID: "3306130"
      SUPERSEDES_IN_PROGRESS: ${{ (github.event.action == 'edited' || github.event.action == 'synchronize' || github.event.action == 'ready_for_review') && 'true' || 'false' }}
    steps:
      - name: Debounce bursty metadata events
        if: ${{ github.event.action == 'labeled' || github.event.action == 'unlabeled' }}
        run: sleep 20

      - name: Require trusted issue command source
        id: trust
        env:
          EVENT_NAME: ${{ github.event_name }}
          EVENT_ACTION: ${{ github.event.action }}
          COMMENT_AUTHOR_ASSOCIATION: ${{ github.event.comment.author_association || '' }}
          ISSUE_AUTHOR_ASSOCIATION: ${{ github.event.issue.author_association || '' }}
          PR_AUTHOR_ASSOCIATION: ${{ github.event.pull_request.author_association || '' }}
        run: |
          case "$EVENT_NAME" in
            issue_comment) author_association="$COMMENT_AUTHOR_ASSOCIATION" ;;
            issues) author_association="$ISSUE_AUTHOR_ASSOCIATION" ;;
            pull_request_target) author_association="$PR_AUTHOR_ASSOCIATION" ;;
            *) author_association="" ;;
          esac
          case "$EVENT_NAME:$EVENT_ACTION:$author_association" in
            pull_request_target:*:*) allowed=true ;;
            issues:labeled:*|issues:unlabeled:*) allowed=true ;;
            issues:*:OWNER|issues:*:MEMBER|issues:*:COLLABORATOR) allowed=true ;;
            issue_comment:*:OWNER|issue_comment:*:MEMBER|issue_comment:*:COLLABORATOR) allowed=true ;;
            *) allowed=false ;;
          esac
          echo "allowed=$allowed" >> "$GITHUB_OUTPUT"
          if [ "$allowed" != "true" ]; then
            echo "::notice::Skipping ClawSweeper dispatch for untrusted $EVENT_NAME author association."
          fi

      - name: Create ClawSweeper dispatch token
        id: token
        if: ${{ steps.trust.outputs.allowed == 'true' && env.HAS_CLAWSWEEPER_APP_PRIVATE_KEY == 'true' }}
        uses: actions/create-github-app-token@bcd2ba49218906704ab6c1aa796996da409d3eb1 # v3.2.0
        with:
          app-id: ${{ env.CLAWSWEEPER_APP_ID }}
          private-key: ${{ secrets.CLAWSWEEPER_APP_PRIVATE_KEY }}
          owner: openclaw
          repositories: clawsweeper
          permission-contents: write

      - name: Create target comment token
        id: target_token
        if: ${{ steps.trust.outputs.allowed == 'true' && github.event_name == 'issue_comment' && env.HAS_CLAWSWEEPER_APP_PRIVATE_KEY == 'true' }}
        uses: actions/create-github-app-token@bcd2ba49218906704ab6c1aa796996da409d3eb1 # v3.2.0
        with:
          app-id: ${{ env.CLAWSWEEPER_APP_ID }}
          private-key: ${{ secrets.CLAWSWEEPER_APP_PRIVATE_KEY }}
          owner: ${{ github.repository_owner }}
          repositories: ${{ github.event.repository.name }}
          permission-issues: write
          permission-pull-requests: read

      - name: Dispatch exact ClawSweeper review
        if: ${{ steps.trust.outputs.allowed == 'true' && github.event_name != 'issue_comment' }}
        env:
          GH_TOKEN: ${{ steps.token.outputs.token }}
          TARGET_REPO: ${{ github.repository }}
          ITEM_NUMBER: ${{ github.event.issue.number || github.event.pull_request.number }}
          ITEM_KIND: ${{ github.event_name == 'pull_request_target' && 'pull_request' || 'issue' }}
          SOURCE_EVENT: ${{ github.event_name }}
          SOURCE_ACTION: ${{ github.event.action }}
        run: |
          if [ -z "$GH_TOKEN" ]; then
            echo "::notice::Skipping ClawSweeper dispatch because no dispatch credential is configured."
            exit 0
          fi
          payload="$(jq -nc \
            --arg target_repo "$TARGET_REPO" \
            --argjson item_number "$ITEM_NUMBER" \
            --arg item_kind "$ITEM_KIND" \
            --arg source_event "$SOURCE_EVENT" \
            --arg source_action "$SOURCE_ACTION" \
            --argjson supersedes_in_progress "$SUPERSEDES_IN_PROGRESS" \
            '{event_type:"clawsweeper_item",client_payload:{target_repo:$target_repo,item_number:$item_number,item_kind:$item_kind,source_event:$source_event,source_action:$source_action,supersedes_in_progress:$supersedes_in_progress}}')"
          gh api repos/openclaw/clawsweeper/dispatches \
            --method POST \
            --input - <<< "$payload"

      - name: Acknowledge and dispatch ClawSweeper comment
        if: ${{ steps.trust.outputs.allowed == 'true' && github.event_name == 'issue_comment' }}
        env:
          DISPATCH_TOKEN: ${{ steps.token.outputs.token }}
          TARGET_TOKEN: ${{ steps.target_token.outputs.token }}
          TARGET_REPO: ${{ github.repository }}
          ITEM_NUMBER: ${{ github.event.issue.number }}
          COMMENT_ID: ${{ github.event.comment.id }}
          COMMENT_BODY: ${{ github.event.comment.body }}
          SOURCE_ACTION: ${{ github.event.action }}
        run: |
          if [ -z "$DISPATCH_TOKEN" ]; then
            echo "::notice::Skipping ClawSweeper dispatch because no dispatch credential is configured."
            exit 0
          fi
          body_file="$RUNNER_TEMP/clawsweeper-comment-body.txt"
          printf '%s\n' "$COMMENT_BODY" > "$body_file"
          if ! grep -Eiq '(^|[[:space:]])@clawsweeper\b|(^|[[:space:]])/(clawsweeper|review|re-review|rerun[ -]?review|status|explain|fix|build|implement|create[ -]?pr|fix[ -]?issue|autofix|auto[ -]?fix|automerge|auto[ -]?merge|approve|stop|autoclose)\b' "$body_file"; then
            echo "No ClawSweeper command found in comment."
            exit 0
          fi
          if [ -n "$TARGET_TOKEN" ]; then
            GH_TOKEN="$TARGET_TOKEN" gh api -X POST \
              -H "Accept: application/vnd.github+json" \
              "repos/$TARGET_REPO/issues/comments/$COMMENT_ID/reactions" \
              -f content="eyes" >/dev/null || true
          fi
          payload="$(jq -nc \
            --arg target_repo "$TARGET_REPO" \
            --argjson item_number "$ITEM_NUMBER" \
            --argjson comment_id "$COMMENT_ID" \
            --arg source_event "issue_comment" \
            --arg source_action "$SOURCE_ACTION" \
            '{event_type:"clawsweeper_comment",client_payload:{target_repo:$target_repo,item_number:$item_number,comment_id:$comment_id,source_event:$source_event,source_action:$source_action}}')"
          GH_TOKEN="$DISPATCH_TOKEN" gh api repos/openclaw/clawsweeper/dispatches \
            --method POST \
            --input - <<< "$payload"
